<h2>Calculate cash-on-cash return</h2><p class="lead">Compare annual pre-tax property cash flow with the total cash invested in the deal.</p><div class="notice">Include all material cash contributed at acquisition, not only the down payment, when you want a realistic denominator.</div><div class="form-grid"><div class="field"><label for="cashflow">Annual pre-tax cash flow</label><input id="cashflow" type="number" value="240000" step="any"></div><div class="field"><label for="down">Down payment / equity invested</label><input id="down" type="number" value="1500000" min="0" step="any"></div><div class="field"><label for="closing">Cash closing costs</label><input id="closing" type="number" value="150000" min="0" step="any"></div><div class="field"><label for="rehab">Upfront rehab / setup cash</label><input id="rehab" type="number" value="100000" min="0" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Cash-on-cash return</span><strong id="coc">—</strong></div><div class="metric"><span>Total cash invested</span><strong id="invested">—</strong></div><div class="metric"><span>Average monthly cash flow</span><strong id="monthly">—</strong></div><div class="metric"><span>Simple cash payback</span><strong id="payback">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('coc').textContent='—';$('invested').textContent='—';$('monthly').textContent='—';$('payback').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const cf=num('cashflow'),d=num('down'),c=num('closing'),r=num('rehab');const inv=d+c+r;if(!(Number.isFinite(cf)&&d>=0&&c>=0&&r>=0&&inv>0))throw 0;const ret=cf/inv*100;$('coc').textContent=fmt(ret,2)+'%';$('invested').textContent=fmt(inv,2);$('monthly').textContent=fmt(cf/12,2);$('payback').textContent=cf>0?fmt(inv/cf,2)+' years':'Not positive';$('note').textContent='Cash-on-cash return is a simple pre-tax cash yield. It ignores appreciation, principal paydown, income tax and the time value of money.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
